PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS countries (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS systems (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS records (id TEXT PRIMARY KEY, country TEXT NOT NULL REFERENCES countries(id), system TEXT NOT NULL REFERENCES systems(id), data TEXT NOT NULL CHECK(json_valid(data)), version INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL, UNIQUE(country, system));
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, title TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role TEXT NOT NULL, text TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS messages_conversation ON messages(conversation_id, created_at);
CREATE TABLE IF NOT EXISTS context_summaries(conversation_id TEXT PRIMARY KEY REFERENCES conversations(id) ON DELETE CASCADE, covered INTEGER NOT NULL, summary TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, conversation_id TEXT, model TEXT NOT NULL, status TEXT NOT NULL, error TEXT, started_at TEXT NOT NULL, ended_at TEXT);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), name TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS artifacts (id TEXT PRIMARY KEY, conversation_id TEXT, run_id TEXT, name TEXT NOT NULL, path TEXT NOT NULL UNIQUE, mime TEXT NOT NULL, hash TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, url TEXT, published_at TEXT, collected_at TEXT NOT NULL, error TEXT);
CREATE TABLE IF NOT EXISTS research (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), record_id TEXT NOT NULL, template_version TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS changes (id INTEGER PRIMARY KEY, record_id TEXT NOT NULL, run_id TEXT NOT NULL, before_data TEXT, after_data TEXT NOT NULL, reason TEXT NOT NULL, evidence TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS forecasts (id INTEGER PRIMARY KEY, record_id TEXT NOT NULL, run_id TEXT, data_version INTEGER NOT NULL, data TEXT NOT NULL, computed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, conversation_id TEXT, run_id TEXT, data_version INTEGER NOT NULL, basis_date TEXT NOT NULL, markdown TEXT NOT NULL, path TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_contexts (screen_id TEXT PRIMARY KEY, conversation_id TEXT, version INTEGER NOT NULL, state TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_commands (id TEXT PRIMARY KEY, screen_id TEXT NOT NULL, conversation_id TEXT NOT NULL, run_id TEXT NOT NULL, expected_version INTEGER NOT NULL, data TEXT NOT NULL, status TEXT NOT NULL, result TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS app_commands_screen ON app_commands(screen_id, status);
-- 데이터 수집(004): 공통 열 source_id·confidence(0~1)·collected_at을 함께 둔다. JSON은 기존 규칙대로 TEXT에 저장한다.
CREATE TABLE IF NOT EXISTS system_links (system TEXT NOT NULL REFERENCES systems(id), model TEXT NOT NULL, maker TEXT, is_group INTEGER NOT NULL DEFAULT 0 CHECK(is_group IN (0,1)), relation TEXT NOT NULL, source_id TEXT, confidence REAL CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1), collected_at TEXT, PRIMARY KEY(system, model));
CREATE TABLE IF NOT EXISTS export_tiers (country TEXT NOT NULL, system TEXT NOT NULL, tier INTEGER NOT NULL CHECK(tier IN (1,2,3)), tier_reasons TEXT NOT NULL CHECK(json_valid(tier_reasons)), tier_checked_at TEXT NOT NULL, source_id TEXT, confidence REAL CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1), collected_at TEXT, PRIMARY KEY(country, system));
CREATE TABLE IF NOT EXISTS export_controls (id TEXT PRIMARY KEY, country TEXT NOT NULL, regime TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','suspended','lifted','partial')), started TEXT, ended TEXT, url TEXT, source_id TEXT, confidence REAL CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1), collected_at TEXT);
CREATE INDEX IF NOT EXISTS export_controls_country ON export_controls(country);
CREATE TABLE IF NOT EXISTS neighbors (country TEXT NOT NULL, neighbor TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('land','sea','rival')), tension REAL, components TEXT CHECK(components IS NULL OR json_valid(components)), computed_at TEXT, source_id TEXT, confidence REAL CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1), collected_at TEXT, PRIMARY KEY(country, neighbor));
CREATE TABLE IF NOT EXISTS inventory (id TEXT PRIMARY KEY, country TEXT NOT NULL, system TEXT NOT NULL, model TEXT NOT NULL, quantity INTEGER, delivered_year INTEGER, service_life INTEGER, retire_year INTEGER, supplier TEXT, source_id TEXT, confidence REAL CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1), collected_at TEXT);
CREATE INDEX IF NOT EXISTS inventory_country_system ON inventory(country, system);
CREATE TABLE IF NOT EXISTS budgets (country TEXT NOT NULL, year INTEGER NOT NULL, usd_m REAL, gdp_pct REAL, yoy_pct REAL, gdp_usd_m REAL, source_id TEXT, confidence REAL CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1), collected_at TEXT, PRIMARY KEY(country, year));
CREATE TABLE IF NOT EXISTS signals (id TEXT PRIMARY KEY, country TEXT NOT NULL, system TEXT NOT NULL, model TEXT, maker TEXT, supplier TEXT, stage TEXT NOT NULL CHECK(stage IN ('review','tender','selection','contract','delivery','cancelled')), quantity INTEGER, value_usd_m REAL, expected_year INTEGER, published_at TEXT, url TEXT, note TEXT, source_id TEXT, confidence REAL CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1), collected_at TEXT);
CREATE INDEX IF NOT EXISTS signals_country_system ON signals(country, system);
CREATE TABLE IF NOT EXISTS consumption (id TEXT PRIMARY KEY, conflict TEXT NOT NULL, user_country TEXT NOT NULL, target_country TEXT, system TEXT NOT NULL, model TEXT, quantity INTEGER NOT NULL, period TEXT, kind TEXT NOT NULL DEFAULT 'loss' CHECK(kind IN ('loss','donation','expenditure')), source_id TEXT, confidence REAL CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1), collected_at TEXT);
CREATE INDEX IF NOT EXISTS consumption_country_system ON consumption(user_country, system);
CREATE TABLE IF NOT EXISTS supplier_capacity (maker TEXT NOT NULL, model TEXT NOT NULL, year INTEGER NOT NULL, annual_output INTEGER, backlog INTEGER, source_id TEXT, confidence REAL CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1), collected_at TEXT, PRIMARY KEY(maker, model, year));
CREATE TABLE IF NOT EXISTS domestic_capability (country TEXT NOT NULL, system TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('none','development','production')), program TEXT, source_id TEXT, confidence REAL CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1), collected_at TEXT, PRIMARY KEY(country, system));
CREATE TABLE IF NOT EXISTS weights (factor TEXT PRIMARY KEY, weight REAL NOT NULL, note TEXT);
CREATE TABLE IF NOT EXISTS pair_events (source TEXT NOT NULL, country TEXT NOT NULL, counterpart TEXT NOT NULL, period TEXT NOT NULL, events REAL, fatalities REAL, goldstein REAL, source_id TEXT, confidence REAL CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1), collected_at TEXT, PRIMARY KEY(source, country, counterpart, period));
-- 수집 작업 기록(005): 채팅 도구·CLI 실행 이력, 출처별 동시 실행 방지, 진행 상황
CREATE TABLE IF NOT EXISTS ingest_runs (id TEXT PRIMARY KEY, source TEXT NOT NULL, params TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(params)), dry_run INTEGER NOT NULL CHECK(dry_run IN (0,1)), status TEXT NOT NULL CHECK(status IN ('running','cancelling','completed','failed','cancelled')), progress TEXT, summary TEXT CHECK(summary IS NULL OR json_valid(summary)), error TEXT, conversation_id TEXT, run_id TEXT, owner TEXT, started_at TEXT NOT NULL, heartbeat_at TEXT NOT NULL, ended_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_running_ingest ON ingest_runs(source) WHERE status IN ('running','cancelling');
CREATE INDEX IF NOT EXISTS ingest_runs_source ON ingest_runs(source, started_at);
INSERT OR IGNORE INTO metadata VALUES ('revision', '1');
INSERT OR IGNORE INTO schema_migrations VALUES (1, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
